mapper.select:
SELECT
    (SELECT COUNT(0)
     FROM account_login_record alr
     JOIN account a ON a.uid = alr.uid AND a.region_id = alr.region_id
     WHERE alr.create_time BETWEEN #{startTime} AND #{endTime}
     ) AS loginSuccesses,
    (SELECT COUNT(0)
     FROM account_login_record alr
     JOIN account a ON a.uid = alr.uid AND a.region_id = alr.region_id
     WHERE alr.create_time BETWEEN #{startTime} AND #{endTime}
       AND alr.login_type IN (2, 3, 4, 6, 9)
     ) AS thirdLoginSuccesses
